BEGIN;
ALTER TABLE public.redirects DROP CONSTRAINT redirects_pending_tenant_fence;
ALTER TABLE public.redirect_events DROP CONSTRAINT redirect_events_pending_tenant_fence;
ALTER TABLE public.redirect_link_conversions DROP CONSTRAINT redirect_link_conversions_pending_tenant_fence;
ALTER TABLE public.redirect_link_customers DROP CONSTRAINT redirect_link_customers_pending_tenant_fence;
DO $$ DECLARE fence text; BEGIN
 SELECT conname INTO fence FROM pg_constraint WHERE conrelid='public.redirect_workspaces'::regclass AND contype='c' AND pg_get_constraintdef(oid) LIKE '%status%provisioning%is_legacy%';
 IF fence IS NULL THEN RAISE EXCEPTION 'Missing activation fixture fence';END IF;
 EXECUTE format('ALTER TABLE public.redirect_workspaces DROP CONSTRAINT %I',fence);
END $$;
DO $$ DECLARE actor uuid:=gen_random_uuid();owner_id uuid:=gen_random_uuid();workspace uuid:=gen_random_uuid();link uuid:=gen_random_uuid();click uuid:=gen_random_uuid();result jsonb; BEGIN
 INSERT INTO auth.users(id,email_confirmed_at,created_at) VALUES(actor,now(),now()-interval '1 hour'),(owner_id,now(),now()-interval '1 day');
 INSERT INTO public.redirect_workspaces(id,name,slug) VALUES(workspace,'Native signup source','native-signup-source');
 INSERT INTO redirect_internal.workspace_owners(workspace_id,user_id) VALUES(workspace,owner_id);
 UPDATE public.redirect_workspaces SET status='active' WHERE id=workspace;
 INSERT INTO public.redirects(id,workspace_id,type,slug,target) VALUES(link,workspace,'SHORT','native-signup-source','https://example.org/signup');
 INSERT INTO public.redirect_events(workspace_id,redirect_id,click_id,ts,path,status) VALUES(workspace,link,click,now()-interval '2 hours','/native-signup',302);
 PERFORM set_config('role','service_role',true);
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-session-actor',actor,'x-qg-redirect-workspace','invalid-visitor-selection')::text,true);
 result:=public.record_redirect_signup(actor,click);
 IF (result->>'duplicate')::boolean THEN RAISE EXCEPTION 'First signup was duplicate';END IF;
 IF NOT (public.record_redirect_signup(actor,click)->>'duplicate')::boolean THEN RAISE EXCEPTION 'Signup replay was not idempotent';END IF;
 IF (SELECT count(*) FROM public.redirect_link_conversions WHERE workspace_id=workspace)<>1 OR NOT EXISTS(SELECT FROM public.redirect_link_conversions WHERE workspace_id=workspace AND click_id=click AND kind='lead' AND customer_key='native:'||actor AND provider_event_id='native:signup:'||actor AND event_name='Sign up' AND amount IS NULL AND occurred_at=now()-interval '1 hour') THEN RAISE EXCEPTION 'Native fixed payload or source attribution changed';END IF;
 IF (SELECT count(*) FROM public.redirect_events WHERE workspace_id=workspace)<>1 OR EXISTS(SELECT FROM public.redirect_workspace_members WHERE workspace_id=workspace AND user_id=actor) THEN RAISE EXCEPTION 'Signup created a visit or required source membership';END IF;
 BEGIN PERFORM public.record_redirect_signup(actor,gen_random_uuid());RAISE EXCEPTION 'Unknown click accepted';EXCEPTION WHEN no_data_found THEN NULL;END;
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-session-actor',owner_id)::text,true);
 PERFORM set_config('role','service_role',true);
 BEGIN PERFORM public.record_redirect_signup(actor,click);RAISE EXCEPTION 'Forged actor accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-session-actor',actor)::text,true);
 RESET ROLE;
 UPDATE auth.users SET email_confirmed_at=NULL WHERE id=actor;
 PERFORM set_config('role','service_role',true);
 BEGIN PERFORM public.record_redirect_signup(actor,click);RAISE EXCEPTION 'Unverified account accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 RESET ROLE;
 UPDATE auth.users SET email_confirmed_at=now(),created_at=now()-interval '3 hours' WHERE id=actor;
 PERFORM set_config('role','service_role',true);
 BEGIN PERFORM public.record_redirect_signup(actor,click);RAISE EXCEPTION 'Post-registration click accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 RESET ROLE;
 UPDATE auth.users SET created_at=now()-interval '1 hour' WHERE id=actor;
 UPDATE public.redirect_events SET ts=now()-interval '32 days' WHERE workspace_id=workspace;
 PERFORM set_config('role','service_role',true);
 BEGIN PERFORM public.record_redirect_signup(actor,click);RAISE EXCEPTION 'Expired attribution window accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 UPDATE public.redirect_workspaces SET status='provisioning' WHERE id=workspace;
 PERFORM set_config('role','service_role',true);
 BEGIN PERFORM public.record_redirect_signup(actor,click);RAISE EXCEPTION 'Inactive source accepted';EXCEPTION WHEN no_data_found THEN NULL;END;
 IF has_function_privilege('authenticated','public.record_redirect_signup(uuid,uuid)','execute') OR has_function_privilege('anon','redirect_internal.registered_account_created_at(uuid)','execute') OR has_function_privilege('authenticated','redirect_internal.record_conversion_for_workspace(uuid,jsonb,uuid,timestamptz)','execute') THEN RAISE EXCEPTION 'Native signup helper exposed';END IF;
END $$;
ROLLBACK;
